11	/* !
12	 * \file ai_infra_matmul_simplifiedkey.h
13	 * \brief
14	 */
15	
16	#ifndef __OP_HOST_MATMUL_V3_SIMPILIFIEDKEY_H__
17	#define __OP_HOST_MATMUL_V3_SIMPILIFIEDKEY_H__
18	
19	#include "exe_graph/runtime/tiling_context.h"
20	#include "../../../common/inc/error_util.h"
21	
22	namespace optiling {
23	inline ge::graphStatus GenSimplifiedKey(gert::TilingContext *context, ge::char_t *simplifiedKey)
24	{
25	    static const size_t destMax = 100;
26	    static const size_t maxLenSimplifiedKey = 256;
27	    static const int32_t INPUT0_INDEX = 0;
28	    static const int32_t INPUT1_INDEX = 1;
29	    static const int32_t BIAS_INDEX = 2;
30	    OP_LOGI(context->GetNodeName(), "Enter genSimplifiedKey.");
31	    OP_TILING_CHECK(simplifiedKey == nullptr, CUBE_INNER_ERR_REPORT(context->GetNodeName(), "simplifiedKey is null"),
32	        return ge::GRAPH_FAILED);
33	
34	    OPS_CHECK_NULL_WITH_CONTEXT(context, context->GetInputDesc(INPUT0_INDEX));
35	    OPS_CHECK_NULL_WITH_CONTEXT(context, context->GetInputDesc(INPUT1_INDEX));
36	    OPS_CHECK_NULL_WITH_CONTEXT(context, context->GetOutputDesc(0));
37	
38	    auto input0Format = context->GetInputDesc(INPUT0_INDEX)->GetStorageFormat();
39	    auto input1Format = context->GetInputDesc(INPUT1_INDEX)->GetStorageFormat();
40	    auto outputFormat = context->GetOutputDesc(0)->GetStorageFormat();
41	    auto input0DataType = context->GetInputDesc(INPUT0_INDEX)->GetDataType();
42	    auto input1DataType = context->GetInputDesc(INPUT1_INDEX)->GetDataType();
43	    auto outputDataType = context->GetOutputDesc(0)->GetDataType();
44	    auto biasDataType = input0DataType;
45	    // 二进制发布json有无bias场景合并为同一个json发布，当无法获取bias信息时，当前约定使用input0的信息代替
46	    if (context->GetOptionalInputDesc(BIAS_INDEX) != nullptr) {
47	        biasDataType = context->GetOptionalInputDesc(BIAS_INDEX)->GetDataType();
48	    }
49	
50	    std::string simpleKeyTemp = "";
51	    strcat_s(simplifiedKey, destMax, "diy,");
52	    simpleKeyTemp.append(std::to_string(input0Format))
53	        .append("/")
54	        .append(std::to_string(input1Format))
55	        .append("/")
56	        .append(std::to_string(ge::FORMAT_ND))
57	        .append("/") // bias的format均为FormatND,因此约束为仅通过FORMAT_ND参与匹配
58	        .append(std::to_string(outputFormat))
59	        .append("/")
60	        .append(std::to_string(input0DataType))
61	        .append("/")
62	        .append(std::to_string(input1DataType))
63	        .append("/")
64	        .append(std::to_string(biasDataType))
65	        .append("/")
66	        .append(std::to_string(outputDataType));
67	    errno_t err = strcat_s(simplifiedKey, destMax, simpleKeyTemp.c_str());
68	    if (err != 0) {
69	        std::cerr << "Error: strcat_s failed with error code " << err << std::endl;
70	        return ge::GRAPH_FAILED;
71	    }
72	
73	    OP_TILING_CHECK(strlen(simplifiedKey) > maxLenSimplifiedKey,
74	        CUBE_INNER_ERR_REPORT(context->GetNodeName(), "len of simplifiedKey exceeds max length."),
75	        return ge::GRAPH_FAILED);
76	
77	    return ge::GRAPH_SUCCESS;
78	}
79	}
80	#endif // __OP_HOST_MATMUL_V3_SIMPILIFIEDKEY_H__
