30	void L2Cache::SetL2CacheFlagBase(bool &aEnableL2Cache, bool &bEnableL2Cache) const
31	{
32	    auto &tileL2cache = tilingData_.tileL2cacheTiling;
33	    if (tileL2cache.mTileCntL2 > 1 || tileL2cache.nTileCntL2 > 1) {
34	        bEnableL2Cache = tileL2cache.mTileCntL2 > 1;
35	        aEnableL2Cache = tileL2cache.nTileCntL2 > 1;
36	        return;
37	    }
38	
39	    auto &matmulTiling = tilingData_.matmulTiling;
40	    // m切多核
41	    if (static_cast<uint64_t>(matmulTiling.singleCoreM) < args_.mValue) {
42	        bEnableL2Cache = true;
43	    }
44	    // n切多核
45	    if (static_cast<uint64_t>(matmulTiling.singleCoreN) < args_.nValue) {
46	        aEnableL2Cache = true;
47	    }
48	    // 判断单核是否可以全载,此场景K可以全载
49	    uint64_t mCnt = MathUtil::CeilDivision(static_cast<uint64_t>(args_.mValue), matmulTiling.singleCoreM);
50	    uint64_t nCnt = MathUtil::CeilDivision(static_cast<uint64_t>(args_.nValue), matmulTiling.singleCoreN);
51	    uint64_t totalCnt = mCnt * nCnt;
52	    uint64_t round = MathUtil::CeilDivision(totalCnt, matmulTiling.usedCoreNum);
53	    bool mFullLoad = (round <= 1UL);
54	    bool nFullLoad = (round <= 1UL);
55	    if (!mFullLoad && !nFullLoad) {
56	        bEnableL2Cache = true;
57	    }
58	}
