64	        l2CacheFlag |= (1U << ALL_L2_ENABLE_BIT);
65	        OP_LOGD(args_.opName, "l2CacheFlag: %u", l2CacheFlag);
66	        return;
67	    }
68	
69	    if (!aEnableL2Cache) {
70	        l2CacheFlag |= (1U << A_L2_DISABLE_BIT);
71	    }
72	
73	    if (!bEnableL2Cache) {
74	        l2CacheFlag |= (1U << B_L2_DISABLE_BIT);
75	    }
76	
77	    if (!cEnableL2Cache) {
78	        l2CacheFlag |= (1U << C_L2_DISABLE_BIT);
79	    }
80	
81	    if (!biasEnableL2Cache) {
82	        l2CacheFlag |= (1U << BIAS_L2_DISABLE_BIT);
83	    }
84	
85	    OP_LOGI(args_.opName, "l2CacheFlag: %u", l2CacheFlag);
86	}
87	
88	void L2Cache::SetL2CacheFlag(TilingEnable tilingEnable, uint64_t l2Size, uint32_t &l2CacheFlag)
89	{
