101	        args_.mValue, args_.nValue, args_.kValue,
102	        matmulTiling.singleCoreM, matmulTiling.singleCoreN, matmulTiling.singleCoreK,
103	        matmulTiling.baseM, matmulTiling.baseN, matmulTiling.baseK,
104	        matmulTiling.stepM, matmulTiling.stepN, matmulTiling.stepKa, matmulTiling.stepKb,
105	        matmulTiling.depthA1, matmulTiling.depthB1,
106	        static_cast<int32_t>(tilingEnable.tilingEnableSplitCore),
107	        static_cast<int32_t>(tilingEnable.tilingEnableFullLoad),
108	        static_cast<int32_t>(tilingEnable.tilingEnableFixOpti));
