11	/*!
12	 * \file mat_mul_nd2nz_kernel.h
13	 * \brief
14	 */
15	#ifndef __OP_KERNEL_MATMUL_V3_ND2NZ_KERNEL_H__
16	#define __OP_KERNEL_MATMUL_V3_ND2NZ_KERNEL_H__
17	
18	#include "ai_infra_matmul_nd2nz_util.h"
19	
20	using namespace AscendC;
21	using namespace matmul;
22	#if defined(__CCE_KT_TEST__)
23	using namespace std;
24	#endif
25	
26	template <class T>
27	class KernelND2NZMM {
28	 public:
29	    __aicore__ inline KernelND2NZMM(){};
30	    __aicore__ inline void CopyIn(uint64_t progress, LocalTensor<T>& dstLocal);
31	    __aicore__ inline void CopyOutMM(uint64_t progress, LocalTensor<T>& srcLocal);
32	    __aicore__ inline void PadD(uint64_t progress, LocalTensor<T>& dstLocal, LocalTensor<T>& srcLocal,
33	                                int eventIn, int eventOut);
34	    __aicore__ inline void Init(GM_ADDR dst, GM_ADDR src, uint32_t height, uint32_t width, uint32_t batch,
35	                                TBuf<TPosition::VECCALC>& ubBuffer, uint32_t usedCoreNum);
36	    template <ND2NZ_DB_TYPE TYPE, bool noZero = false>
37	    __aicore__ inline bool SetBufMM();
38	    template<Nd2NzMode mode = Nd2NzMode::MULTI_CORE>
39	    __aicore__ inline bool ProcessMM();
40	    template<Nd2NzMode mode>
41	    __aicore__ inline void ProcessInOutDB();
42	    template<Nd2NzMode mode>
43	    __aicore__ inline void ProcessNoDBReuse();
44	    template<Nd2NzMode mode>
45	    __aicore__ inline void ProcessOutDBReuse();
46	
47	 private:
48	    TBuf<TPosition::VECCALC>* ubPtr_;
49	    GlobalTensor<T> srcGM;
50	    GlobalTensor<T> dstGM;
51	    LocalTensor<T> inBuf_;
52	    LocalTensor<T> inBuf2_;
53	    LocalTensor<T> midBuf_;
54	    LocalTensor<T> outBuf_;
55	    LocalTensor<T> outBuf2_;
56	    LocalTensor<T> zeroBuf_;
57	    uint32_t padSize_;
58	    uint32_t height_;
59	    uint32_t hAligned_;
60	    uint32_t width_;
61	    uint32_t batch_;
62	    uint32_t wTail_;
63	    uint32_t hBuffer_;
64	    uint32_t nFullProgress_;
65	    uint32_t heightTotalTail_;
66	    uint16_t hPad_;
67	    uint32_t blockDim_;
68	    uint32_t blockIdx_;
69	    uint32_t hBlockNum_;
70	    uint32_t copyInSize_;
71	    uint64_t c0_;
72	    uint32_t copyInRepeat_;
73	    uint16_t widthBlockTotal_;
74	    bool noPadD_;
75	};
76	
77	template <class T>
78	__aicore__ inline void KernelND2NZMM<T>::CopyIn(uint64_t progress, LocalTensor<T>& dstLocal) {
79	    uint64_t curCopyInSize = progress == nFullProgress_ ? heightTotalTail_ * width_ : copyInSize_;
80	    uint64_t gmInOffset = copyInSize_ * progress;
81	    DataCopyExtParams copyParams{DEFAULT_DATA_COPY_NBURST, static_cast<uint32_t>(curCopyInSize * sizeof(T)),
82	                                 DEFAULT_DATA_COPY_STRIDE, DEFAULT_DATA_COPY_STRIDE, 0};
83	    DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
84	    DataCopyPad(dstLocal, srcGM[gmInOffset], copyParams, padParams);
85	}
86	
87	template <class T>
88	__aicore__ inline void KernelND2NZMM<T>::CopyOutMM(uint64_t progress, LocalTensor<T>& srcLocal) {
89	    uint64_t oneColSizeGM = Align2(height_ * batch_, ALIGNED_H) * c0_;
90	    uint64_t oneColSize = hBuffer_ * c0_;
91	    uint32_t copyOutSize = progress == nFullProgress_ ? Align2(heightTotalTail_, ALIGNED_H) * c0_ : oneColSize;
92	    if (progress == nFullProgress_) {
93	        for (uint32_t i = 0; i < widthBlockTotal_; i++) {
94	            Duplicate(srcLocal[oneColSize * i + heightTotalTail_ * c0_], T(0), padSize_);
95	        }
96	    }
97	    SetFlag<HardEvent::V_MTE3>(EVENT_ID0);
98	    WaitFlag<HardEvent::V_MTE3>(EVENT_ID0);
99	
100	    for (uint32_t i = 0; i < widthBlockTotal_; i++) {
101	        DataCopy(dstGM[oneColSizeGM * i + oneColSize * progress], srcLocal[oneColSize * i], copyOutSize);
102	    }
103	}
104	
105	template <class T>
106	__aicore__ inline void KernelND2NZMM<T>::PadD(uint64_t progress, LocalTensor<T>& dstLocal, LocalTensor<T>& srcLocal,
107	                                            int eventIn, int eventOut) {
108	    if (wTail_ == 0) {
109	        PadDAligned<T>(progress, dstLocal, srcLocal, eventIn, eventOut, width_, c0_, hBlockNum_, true);
110	    } else {
111	        PadDMain<T>(progress, dstLocal, srcLocal, midBuf_, zeroBuf_, eventIn, eventOut, width_, c0_,
112	                    hBlockNum_, copyInRepeat_, hBuffer_, wTail_, true);
113	    }
114	}
115	
116	template <class T>
117	__aicore__ inline void KernelND2NZMM<T>::Init(GM_ADDR dst, GM_ADDR src, uint32_t height, uint32_t width, uint32_t batch,
118	                                            TBuf<TPosition::VECCALC>& ubBuffer, uint32_t usedCoreNum)
119	{
120	    height_ = height;
121	    width_ = width;
122	    batch_ = batch;
123	    uint32_t hTotal = height_ * batch_;
124	
125	    blockDim_ = usedCoreNum;
126	    blockIdx_ = GetBlockIdx();
127	
128	    c0_ = BLOCK_SIZE_BYTE / sizeof(T);
129	
130	    srcGM.SetGlobalBuffer((__gm__ T*)src);
131	    dstGM.SetGlobalBuffer((__gm__ T*)dst);
132	    ubPtr_ = &ubBuffer;
133	
134	    noPadD_ = (width_ == c0_);
135	
136	    uint32_t batchTail = height_ % ALIGNED_H;
137	    hPad_ = batchTail == 0 ? 0 : ALIGNED_H - batchTail;
138	
139	    padSize_ = hPad_ * c0_;
140	
141	    hAligned_ = Align2(height_, ALIGNED_H);
142	
143	    uint32_t widthBlock = width_ / c0_;
144	    wTail_ = width_ & (c0_ - 1);
145	
146	    widthBlockTotal_ = wTail_ ? widthBlock + 1 : widthBlock;
147	}
148	
149	template <class T>
150	template <ND2NZ_DB_TYPE TYPE, bool noZero>
151	__aicore__ inline bool KernelND2NZMM<T>::SetBufMM() {
152	    uint32_t hTotal = height_ * batch_;
153	    uint32_t wAligned = Align2(width_, c0_);
154	
155	    uint32_t ubTotalWidth = 0;
156	
157	    if constexpr (TYPE == ND2NZ_DB_TYPE::IN_OUTPUT) {
158	        // If both of CopyIn and CopyOut with DB, total ub size calculates one midbuf + two inputbuf + two outbuf size.
159	        ubTotalWidth = 3 * width_ + 2 * wAligned;
160	    }
161	    if constexpr (TYPE == ND2NZ_DB_TYPE::OUTPUT) {
162	        // If only CopyOut with DB, total ub size calculates one midbuf + two outbuf size. (inputbuf can reuse midbuf).
163	        ubTotalWidth = width_ + 2 * wAligned;
164	    }
165	    if constexpr (TYPE == ND2NZ_DB_TYPE::NO_DB_REUSE_OUTPUT) {
166	        // If none of CopyIn or Copyout with DB, calculates one midbuf + one outbuf size. (inputbuf can reuse midbuf).
167	        ubTotalWidth = width_ + wAligned;
168	    }
169	
170	    if (!(width_ > c0_) && !noZero) {
171	        ubTotalWidth += width_;
172	    }
173	
174	    uint32_t hMax = TOTAL_UB_SIZE / sizeof(T) / ubTotalWidth;
175	
176	    uint32_t hBlockNumEle = M_BLOCK_NUM_ELE_LIST[wTail_] * 2 / sizeof(T);
177	    hBlockNumEle = width_ == 1 ? 1 : hBlockNumEle;
178	    hBlockNumEle = hBlockNumEle == 0 ? 1 : hBlockNumEle;
179	    uint32_t gcd = GCD_LIST[wTail_];
180	    if constexpr (sizeof(T) == sizeof(float)) {
181	        gcd = wTail_ == 0 ? 8 : gcd; // if float, one Transdata5HD only need 8 aligned instead of 16 aligned.
182	    }
183	
184	    uint32_t hEle = hBlockNumEle * ALIGNED_H;
185	    uint32_t eleNum = (hTotal + hEle - 1) / hEle;
186	    uint32_t eleNumTmp = hMax / hEle;
187	    eleNum = min(eleNumTmp, eleNum);
188	    eleNum = eleNum * hBlockNumEle > REPEAT_TIMES_MAX ? (REPEAT_TIMES_MAX / hBlockNumEle) : eleNum;
189	
190	    if (eleNum == 0) {
191	        return false;
192	    }
193	
194	    copyInRepeat_ = eleNum * width_ / gcd;
195	    hBuffer_ = eleNum * hEle;
196	    copyInSize_ = hBuffer_ * width_;
197	    hBlockNum_ = eleNum * hBlockNumEle;
198	    nFullProgress_ = hTotal / hBuffer_;
199	    heightTotalTail_ = hTotal % hBuffer_;
200	
201	    uint32_t ubTail = 0;
202	
203	    midBuf_ = ubPtr_->Get<T>()[ubTail / sizeof(T)];
204	
205	    ubTail += copyInSize_ * sizeof(T);
206	
207	    if ((width_ < c0_) && !noZero) {
208	        zeroBuf_ = ubPtr_->Get<T>()[ubTail / sizeof(T)];
209	        ubTail += copyInSize_ * sizeof(T);
210	    }
211	    if (TYPE == ND2NZ_DB_TYPE::IN_OUTPUT) {
212	        inBuf_ = ubPtr_->Get<T>()[ubTail / sizeof(T)];
213	        ubTail += copyInSize_ * sizeof(T);
214	        inBuf2_ = ubPtr_->Get<T>()[ubTail / sizeof(T)];
215	        ubTail += copyInSize_ * sizeof(T);
216	    }
217	
218	    if (TYPE == ND2NZ_DB_TYPE::IN_OUTPUT || TYPE == ND2NZ_DB_TYPE::OUTPUT ||
219	        TYPE == ND2NZ_DB_TYPE::NO_DB_REUSE_OUTPUT) {
220	        outBuf_ = ubPtr_->Get<T>()[ubTail / sizeof(T)];
221	        ubTail += hBuffer_ * wAligned * sizeof(T);
222	    }
223	    if (TYPE == ND2NZ_DB_TYPE::IN_OUTPUT || TYPE == ND2NZ_DB_TYPE::OUTPUT) {
224	        outBuf2_ = ubPtr_->Get<T>()[ubTail / sizeof(T)];
225	        ubTail += hBuffer_ * wAligned * sizeof(T);
226	    }
227	    if ((width_ < c0_) && !noZero) {
228	        Duplicate(zeroBuf_, T(0), copyInSize_);
229	    }
230	
231	    // PipeBarrier<PIPE_ALL>();
232	    return true;
233	}
234	
235	template <class T>
236	template <Nd2NzMode mode>
237	__aicore__ inline bool KernelND2NZMM<T>::ProcessMM() {
238	    if (width_ % c0_ == 0) {
239	        if (SetBufMM<ND2NZ_DB_TYPE::IN_OUTPUT, true>()) { // issue:when innersize > 49152B, will return false and break.
240	            ProcessInOutDB<mode>();
241	            return true;
242	        }
243	        return false;
244	    } else if (SetBufMM<ND2NZ_DB_TYPE::OUTPUT>()) {
245	        ProcessOutDBReuse<mode>();
246	        return true;
247	    } else if (SetBufMM<ND2NZ_DB_TYPE::NO_DB_REUSE_OUTPUT>()) {
248	        // now max totalwidth = 2 * width + widthalign = 3 * 512B <<< ubsize, so this branch will never be used.
249	        ProcessNoDBReuse<mode>();
250	        return true;
251	    }
252	    return false;
253	}
254	
255	template <class T>
256	template <Nd2NzMode mode>
257	__aicore__ inline void KernelND2NZMM<T>::ProcessInOutDB() {
258	    uint32_t nLoop = heightTotalTail_ ? nFullProgress_ + 1 : nFullProgress_;
259	    uint32_t j = 0;
260	    SetFlag<HardEvent::V_MTE2>(EVENT_ID0);
261	    SetFlag<HardEvent::MTE3_V>(EVENT_ID0);
262	    SetFlag<HardEvent::V_MTE2>(EVENT_ID1);
263	    SetFlag<HardEvent::MTE3_V>(EVENT_ID1);
264	    int32_t start_idx = (mode == Nd2NzMode::MULTI_CORE ? blockIdx_ : GetSubBlockIdx());
265	    for (int32_t i = start_idx; i < nLoop; i += blockDim_, j++) {
266	        if (j % 2 == 1) {
267	            WaitFlag<HardEvent::V_MTE2>(EVENT_ID0);
268	            CopyIn(i, inBuf_);
269	            SetFlag<HardEvent::MTE2_V>(EVENT_ID0);
270	            WaitFlag<HardEvent::MTE2_V>(EVENT_ID0);
271	
272	            PadD(i, outBuf_, inBuf_, EVENT_ID0, EVENT_ID0);
273	
274	            CopyOutMM(i, outBuf_);
275	            SetFlag<HardEvent::MTE3_V>(EVENT_ID0);
276	        } else {
277	            WaitFlag<HardEvent::V_MTE2>(EVENT_ID1);
278	            CopyIn(i, inBuf2_);
279	
280	            SetFlag<HardEvent::MTE2_V>(EVENT_ID0);
281	            WaitFlag<HardEvent::MTE2_V>(EVENT_ID0);
282	
283	            PadD(i, outBuf2_, inBuf2_, EVENT_ID1, EVENT_ID1);
284	
285	            CopyOutMM(i, outBuf2_);
286	            SetFlag<HardEvent::MTE3_V>(EVENT_ID1);
287	        }
288	    }
289	    WaitFlag<HardEvent::V_MTE2>(EVENT_ID0);
290	    WaitFlag<HardEvent::MTE3_V>(EVENT_ID0);
291	    WaitFlag<HardEvent::V_MTE2>(EVENT_ID1);
292	    WaitFlag<HardEvent::MTE3_V>(EVENT_ID1);
293	    if constexpr (mode == Nd2NzMode::MULTI_CORE) {
294	        PipeBarrier<PIPE_ALL>();
295	    }
296	}
297	
298	template <class T>
299	template <Nd2NzMode mode>
300	__aicore__ inline void KernelND2NZMM<T>::ProcessOutDBReuse() {
301	    uint32_t nLoop = heightTotalTail_ ? nFullProgress_ + 1 : nFullProgress_;
302	    uint32_t j = 0;
303	    SetFlag<HardEvent::MTE3_MTE2>(EVENT_ID0);
304	    SetFlag<HardEvent::MTE3_MTE2>(EVENT_ID1);
305	    int32_t start_idx = (mode == Nd2NzMode::MULTI_CORE ? blockIdx_ : GetSubBlockIdx());
306	    for (int32_t i = start_idx; i < nLoop; i += blockDim_, j++) {
307	        if (j % 2 == 1) {
308	            WaitFlag<HardEvent::MTE3_MTE2>(EVENT_ID0);
309	            CopyIn(i, outBuf_);
310	            SetFlag<HardEvent::MTE2_V>(EVENT_ID0);
311	            WaitFlag<HardEvent::MTE2_V>(EVENT_ID0);
312	
313	            PadDMain<T>(i, outBuf_, outBuf_, midBuf_, zeroBuf_, 0, 0, width_, c0_,
314	                        hBlockNum_, copyInRepeat_, hBuffer_, wTail_, false);
315	            CopyOutMM(i, outBuf_);
316	            SetFlag<HardEvent::MTE3_MTE2>(EVENT_ID0);
317	        } else {
318	            WaitFlag<HardEvent::MTE3_MTE2>(EVENT_ID1);
319	            CopyIn(i, outBuf2_);
320	            SetFlag<HardEvent::MTE2_V>(EVENT_ID0);
321	            WaitFlag<HardEvent::MTE2_V>(EVENT_ID0);
322	
323	            PadDMain<T>(i, outBuf2_, outBuf2_, midBuf_, zeroBuf_, 0, 0, width_, c0_,
324	                        hBlockNum_, copyInRepeat_, hBuffer_, wTail_, false);
325	            CopyOutMM(i, outBuf2_);
326	            SetFlag<HardEvent::MTE3_MTE2>(EVENT_ID1);
327	        }
328	    }
329	    WaitFlag<HardEvent::MTE3_MTE2>(EVENT_ID0);
330	    WaitFlag<HardEvent::MTE3_MTE2>(EVENT_ID1);
331	    if constexpr (mode == Nd2NzMode::MULTI_CORE) {
332	        PipeBarrier<PIPE_ALL>();
333	    }
334	}
335	
336	template <class T>
337	template <Nd2NzMode mode>
338	__aicore__ inline void KernelND2NZMM<T>::ProcessNoDBReuse() {
339	    uint32_t nLoop = heightTotalTail_ ? nFullProgress_ + 1 : nFullProgress_;
340	    int32_t start_idx = (mode == Nd2NzMode::MULTI_CORE ? blockIdx_ : GetSubBlockIdx());
341	    for (int32_t i = start_idx; i < nLoop; i += blockDim_) {
342	        CopyIn(i, outBuf_);
343	        SetFlag<HardEvent::MTE2_V>(EVENT_ID0);
344	        WaitFlag<HardEvent::MTE2_V>(EVENT_ID0);
345	
346	        PadDMain<T>(i, outBuf_, outBuf_, midBuf_, zeroBuf_, 0, 0, width_, c0_,
347	                    hBlockNum_, copyInRepeat_, hBuffer_, wTail_, false);
348	
349	        CopyOutMM(i, outBuf_);
350	        SetFlag<HardEvent::MTE3_MTE2>(EVENT_ID0);
351	        WaitFlag<HardEvent::MTE3_MTE2>(EVENT_ID0);
352	    }
353	    if constexpr (mode == Nd2NzMode::MULTI_CORE) {
354	        PipeBarrier<PIPE_ALL>();
355	    }
356	}
357	
358	
359	#endif
