/*!
 * \file ai_infra_matmul.cpp
 * \brief
 */

#include "kernel_operator.h"
#if __has_include("arch32/ai_infra_matmul_tiling_key.h")
#include "arch32/ai_infra_matmul_tiling_key.h"
#else
#include "op_kernel/arch32/ai_infra_matmul_tiling_key.h"
#endif
#if __has_include("arch32/ai_infra_matmul_base_kernel.h")
#include "arch32/ai_infra_matmul_base_kernel.h"
#else
#include "op_kernel/arch32/ai_infra_matmul_base_kernel.h"
#endif
#if __has_include("arch32/ai_infra_matmul_cvp_base_kernel.h")
#include "arch32/ai_infra_matmul_cvp_base_kernel.h"
#else
#include "op_kernel/arch32/ai_infra_matmul_cvp_base_kernel.h"
#endif
#if __has_include("arch32/ai_infra_matmul_l1_full_load.h")
#include "arch32/ai_infra_matmul_l1_full_load.h"
#else
#include "op_kernel/arch32/ai_infra_matmul_l1_full_load.h"
#endif

using namespace AscendC;
using namespace matmul;
using namespace AiInfraMatmul;
#ifndef DTYPE_BIAS
#define DTYPE_BIAS half
#endif

#ifndef FORMAT_FRACTAL_NZ
#define FORMAT_FRACTAL_NZ
#endif

#if defined(FORMAT_X1) && FORMAT_X1 == FORMAT_FRACTAL_NZ
constexpr CubeFormat format_x1 = CubeFormat::NZ;
#else
constexpr CubeFormat format_x1 = CubeFormat::ND;
#endif

#if defined(FORMAT_X2) && FORMAT_X2 == FORMAT_FRACTAL_NZ
constexpr CubeFormat format_x2 = CubeFormat::NZ;
#else
constexpr CubeFormat format_x2 = CubeFormat::ND;
#endif

#if defined(FORMAT_Y) && FORMAT_Y == FORMAT_FRACTAL_NZ
constexpr CubeFormat format_y = CubeFormat::NZ;
#else
constexpr CubeFormat format_y = CubeFormat::ND;
#endif

#if defined(FORMAT_X1) && FORMAT_X1 == FORMAT_ND && defined(ORIG_DTYPE_X2) && ORIG_DTYPE_X2 == DT_FLOAT
#define IS_ND_NZ_FP32 1
#else
#define IS_ND_NZ_FP32 0
#endif
// ND_NZ_FP32场景支持走入多个模板

#define MMV3_IMPL(templateFunc, cFormat, ...)                                                                          \
    do {                                                                                                               \
        using cType = MatmulType<AscendC::TPosition::GM, cFormat, DTYPE_Y>;                                            \
        using biasType = MatmulType<AscendC::TPosition::GM, CubeFormat::ND, DTYPE_BIAS>;                               \
        if (tilingData.matmulRunInfo.transA == 0 && tilingData.matmulRunInfo.transB == 0) {                            \
            using aType = MatmulType<AscendC::TPosition::GM, format_x1, DTYPE_X1, false>;                              \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, false>;                              \
            templateFunc<aType, bType, cType, biasType, __VA_ARGS__>(aGM, bGM, cGM, biasGM, tilingData, user);         \
        } else if (tilingData.matmulRunInfo.transA == 1 && tilingData.matmulRunInfo.transB == 0) {                     \
            using aType = MatmulType<AscendC::TPosition::GM, format_x1, DTYPE_X1, true>;                               \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, false>;                              \
            templateFunc<aType, bType, cType, biasType, __VA_ARGS__>(aGM, bGM, cGM, biasGM, tilingData, user);         \
        } else if (tilingData.matmulRunInfo.transA == 0 && tilingData.matmulRunInfo.transB == 1) {                     \
            using aType = MatmulType<AscendC::TPosition::GM, format_x1, DTYPE_X1, false>;                              \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, true>;                               \
            templateFunc<aType, bType, cType, biasType, __VA_ARGS__>(aGM, bGM, cGM, biasGM, tilingData, user);         \
        } else {                                                                                                       \
            using aType = MatmulType<AscendC::TPosition::GM, format_x1, DTYPE_X1, true>;                               \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, true>;                               \
            templateFunc<aType, bType, cType, biasType, __VA_ARGS__>(aGM, bGM, cGM, biasGM, tilingData, user);         \
        }                                                                                                              \
    } while (0)

#define MMV3_IMPL_CLASS(templateClass, aFormat, ...)                                                                   \
    do {                                                                                                               \
        using cType = MatmulType<AscendC::TPosition::GM, format_y, DTYPE_Y>;                                           \
        using biasType = MatmulType<AscendC::TPosition::GM, CubeFormat::ND, DTYPE_BIAS>;                               \
        TPipe pipe;                                                                                                    \
        if (tilingData.matmulRunInfo.transA == 0 && tilingData.matmulRunInfo.transB == 0) {                            \
            using aType = MatmulType<AscendC::TPosition::GM, aFormat, DTYPE_X1, false>;                                \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, false>;                              \
            templateClass<aType, bType, cType, biasType, __VA_ARGS__> op;                                              \
            op.Init(aGM, bGM, cGM, biasGM, offsetWGM, user, &tilingData, &pipe);                                       \
            op.Process();                                                                                              \
        } else if (tilingData.matmulRunInfo.transA == 1 && tilingData.matmulRunInfo.transB == 0) {                     \
            using aType = MatmulType<AscendC::TPosition::GM, aFormat, DTYPE_X1, true>;                                 \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, false>;                              \
            templateClass<aType, bType, cType, biasType, __VA_ARGS__> op;                                              \
            op.Init(aGM, bGM, cGM, biasGM, offsetWGM, user, &tilingData, &pipe);                                       \
            op.Process();                                                                                              \
        } else if (tilingData.matmulRunInfo.transA == 0 && tilingData.matmulRunInfo.transB == 1) {                     \
            using aType = MatmulType<AscendC::TPosition::GM, aFormat, DTYPE_X1, false>;                                \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, true>;                               \
            templateClass<aType, bType, cType, biasType, __VA_ARGS__> op;                                              \
            op.Init(aGM, bGM, cGM, biasGM, offsetWGM, user, &tilingData, &pipe);                                       \
            op.Process();                                                                                              \
        } else {                                                                                                       \
            using aType = MatmulType<AscendC::TPosition::GM, aFormat, DTYPE_X1, true>;                                 \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, true>;                               \
            templateClass<aType, bType, cType, biasType, __VA_ARGS__> op;                                              \
            op.Init(aGM, bGM, cGM, biasGM, offsetWGM, user, &tilingData, &pipe);                                       \
            op.Process();                                                                                              \
        }                                                                                                              \
    } while (0)

// cFormat is for tempCGlobal Nz out, not cTensor out
#define MMV3_IMPL_C_CLASS(templateClass, aFormat, cFormat, ...)                                                        \
    do {                                                                                                               \
        using cType = MatmulType<AscendC::TPosition::GM, cFormat, DTYPE_Y>;                                            \
        using biasType = MatmulType<AscendC::TPosition::GM, CubeFormat::ND, DTYPE_BIAS>;                               \
        TPipe pipe;                                                                                                    \
        if (tilingData.matmulRunInfo.transA == 0 && tilingData.matmulRunInfo.transB == 0) {                            \
            using aType = MatmulType<AscendC::TPosition::GM, aFormat, DTYPE_X1, false>;                                \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, false>;                              \
            templateClass<aType, bType, cType, biasType, __VA_ARGS__> op;                                              \
            op.Init(aGM, bGM, cGM, biasGM, offsetWGM, user, &tilingData, &pipe);                                       \
            op.Process();                                                                                              \
        } else if (tilingData.matmulRunInfo.transA == 1 && tilingData.matmulRunInfo.transB == 0) {                     \
            using aType = MatmulType<AscendC::TPosition::GM, aFormat, DTYPE_X1, true>;                                 \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, false>;                              \
            templateClass<aType, bType, cType, biasType, __VA_ARGS__> op;                                              \
            op.Init(aGM, bGM, cGM, biasGM, offsetWGM, user, &tilingData, &pipe);                                       \
            op.Process();                                                                                              \
        } else if (tilingData.matmulRunInfo.transA == 0 && tilingData.matmulRunInfo.transB == 1) {                     \
            using aType = MatmulType<AscendC::TPosition::GM, aFormat, DTYPE_X1, false>;                                \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, true>;                               \
            templateClass<aType, bType, cType, biasType, __VA_ARGS__> op;                                              \
            op.Init(aGM, bGM, cGM, biasGM, offsetWGM, user, &tilingData, &pipe);                                       \
            op.Process();                                                                                              \
        } else {                                                                                                       \
            using aType = MatmulType<AscendC::TPosition::GM, aFormat, DTYPE_X1, true>;                                 \
            using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, true>;                               \
            templateClass<aType, bType, cType, biasType, __VA_ARGS__> op;                                              \
            op.Init(aGM, bGM, cGM, biasGM, offsetWGM, user, &tilingData, &pipe);                                       \
            op.Process();                                                                                              \
        }                                                                                                              \
    } while (0)

#define MMV3_IMPL_CLASS_TRANS(tilingData, tilingGM, transA, transB, templateClass, ...)                                \
    do {                                                                                                               \
        uint64_t tilingdata_offset =                                                                                   \
            (sizeof(AiInfraMatmulTilingData) > TILINGDATA_OFFSET) ?                                                    \
                0 :                                                                                                    \
                MMV3DivFloor(GetCurrentBlockIdx(), MMV3DivCeil(GetBlockNum(), TILINGDATA_SPLIT_NUM)) *                 \
                    TILINGDATA_OFFSET;                                                                                 \
        GET_TILING_DATA_WITH_STRUCT(AiInfraMatmulTilingData, tilingData, tilingGM + tilingdata_offset);                \
        using cType = MatmulType<AscendC::TPosition::GM, CubeFormat::ND, DTYPE_Y>;                                     \
        using biasType = MatmulType<AscendC::TPosition::GM, CubeFormat::ND, DTYPE_BIAS>;                               \
        TPipe pipe;                                                                                                    \
        using aType = MatmulType<AscendC::TPosition::GM, format_x1, DTYPE_X1, transA>;                                 \
        using bType = MatmulType<AscendC::TPosition::GM, format_x2, DTYPE_X2, transB>;                                 \
        templateClass<aType, bType, cType, biasType, __VA_ARGS__> op;                                                  \
        op.Init(aGM, bGM, cGM, biasGM, offsetWGM, user, &tilingData, &pipe);                                           \
        op.Process();                                                                                                  \
    } while (0)

template <int LOADMODE, int SPLITCOREMODE, int FIXOPTI, int MIXND2NZ, int SPECIALOPT, int FP32ADDMM>
__global__ __aicore__ void ai_infra_matmul(GM_ADDR aGM, GM_ADDR bGM, GM_ADDR biasGM, GM_ADDR offsetWGM, GM_ADDR cGM,
                                           GM_ADDR workspaceGM, GM_ADDR tilingGM)
{
    REGISTER_TILING_DEFAULT(AiInfraMatmulTilingData);
    __gm__ uint8_t *user = GetUserWorkspace(workspaceGM);
    GET_TILING_DATA(tilingData, tilingGM);
#if defined(__CCE_AICORE__) && __CCE_AICORE__ < 220
    if constexpr (LOADMODE == AI_INFRA_MAT_MUL_BASE_FULLLOAD && SPLITCOREMODE == AI_INFRA_MAT_MUL_BASE_SPLIT_K &&
                  FIXOPTI == AI_INFRA_MAT_MUL_BASE_FIXOPTI && MIXND2NZ == AI_INFRA_MAT_MUL_MIXND2NZ_FALSE) {
        MMV3_IMPL_CLASS(AiInfraMatmulBaseKernel, format_x1, AiInfraMatmulBaseBlock, MM_CFG_VEC_ND2NZ);
    }
#elif defined(FORMAT_X2) && FORMAT_X2 == FRACTAL_NZ && !IS_ND_NZ_FP32
    if constexpr (LOADMODE == AI_INFRA_MAT_MUL_BASE_FULLLOAD && SPLITCOREMODE == AI_INFRA_MAT_MUL_BASE_SPLIT_K &&
                  FIXOPTI == AI_INFRA_MAT_MUL_BASE_FIXOPTI && MIXND2NZ == AI_INFRA_MAT_MUL_MIXND2NZ_FALSE &&
                  SPECIALOPT == AI_INFRA_MAT_MUL_K_SHIFT) {
        MMV3_IMPL_CLASS(AiInfraMatmulBaseKernel, format_x1, AiInfraMatmulBaseBlock, MM_CFG_K_SHIFT);
    } else if constexpr (LOADMODE == AI_INFRA_MAT_MUL_BASE_FULLLOAD && SPLITCOREMODE == AI_INFRA_MAT_MUL_BASE_SPLIT_K &&
                         FIXOPTI == AI_INFRA_MAT_MUL_BASE_FIXOPTI && MIXND2NZ == AI_INFRA_MAT_MUL_MIXND2NZ_FALSE) {
        MMV3_IMPL_CLASS(AiInfraMatmulBaseKernel, format_x1, AiInfraMatmulBaseBlock, MM_CFG_NO_PRELOAD);
    }
#else
    if constexpr (LOADMODE == AI_INFRA_MAT_MUL_BASE_FULLLOAD && SPLITCOREMODE == AI_INFRA_MAT_MUL_BASE_SPLIT_K &&
                  FIXOPTI == AI_INFRA_MAT_MUL_BASE_FIXOPTI && MIXND2NZ == AI_INFRA_MAT_MUL_MIXND2NZ_FALSE &&
                  SPECIALOPT == AI_INFRA_MAT_MUL_K_SHIFT) {
        MMV3_IMPL_CLASS(AiInfraMatmulBaseKernel, format_x1, AiInfraMatmulBaseBlock, MM_CFG_K_SHIFT);
    } else if constexpr (LOADMODE == AI_INFRA_MAT_MUL_BASE_FULLLOAD && SPLITCOREMODE == AI_INFRA_MAT_MUL_BASE_SPLIT_K &&
                         FIXOPTI == AI_INFRA_MAT_MUL_BASE_FIXOPTI && MIXND2NZ == AI_INFRA_MAT_MUL_MIXND2NZ_FALSE) {
        MMV3_IMPL_CLASS(AiInfraMatmulBaseKernel, format_x1, AiInfraMatmulBaseBlock, MM_CFG_NO_PRELOAD);
    } else if constexpr (LOADMODE == AI_INFRA_MAT_MUL_AL1_FULLLOAD && SPLITCOREMODE == AI_INFRA_MAT_MUL_BASE_SPLIT_K &&
                         FIXOPTI == AI_INFRA_MAT_MUL_BASE_FIXOPTI && MIXND2NZ == AI_INFRA_MAT_MUL_MIXND2NZ_FALSE) {
        MMV3_IMPL_CLASS(MatmulBaseKernelAL1FullLoad, format_x1, AiInfraMatmulBaseBlock, MM_CFG_MDL);
    } else if constexpr (LOADMODE == AI_INFRA_MAT_MUL_BL1_FULLLOAD && SPLITCOREMODE == AI_INFRA_MAT_MUL_BASE_SPLIT_K &&
                         FIXOPTI == AI_INFRA_MAT_MUL_BASE_FIXOPTI && MIXND2NZ == AI_INFRA_MAT_MUL_MIXND2NZ_FALSE) {
        MMV3_IMPL_CLASS(MatmulBaseKernelBL1FullLoad, format_x1, AiInfraMatmulBaseBlock, MM_CFG_NO_PRELOAD);
    } else if constexpr (LOADMODE == AI_INFRA_MAT_MUL_BL1_FULLLOAD && SPLITCOREMODE == AI_INFRA_MAT_MUL_BASE_SPLIT_K &&
                         FIXOPTI == AI_INFRA_MAT_MUL_BASE_FIXOPTI &&
                         MIXND2NZ == AI_INFRA_MAT_MUL_MIXND2NZ_TRUE_PARALLEL) {
        MMV3_IMPL_CLASS(AiInfraMatmulCvpBaseKernel, format_x1, AiInfraMatmulBaseBlock, MM_CFG_NO_PRELOAD);
    } else {
        MMV3_IMPL_CLASS(AiInfraMatmulBaseKernel, format_x1, AiInfraMatmulBaseBlock, MM_CFG_NO_PRELOAD);
    }
#endif
}

