            workspaceSize_ += ops::CeilAlign(args_.mValue, c0Size) * kALignForN * aDtypeSize_;
        } else {
            workspaceSize_ += ops::CeilAlign(args_.mValue, N_ALIGNED) * kALignForC0 * aDtypeSize_;
        }
    }
    if (args_.nd2nzB) {
        if (args_.isBTrans) {
            workspaceSize_ += ops::CeilAlign(args_.nValue, N_ALIGNED) * kALignForC0 * bDtypeSize_;
        } else {
            workspaceSize_ += ops::CeilAlign(args_.nValue, c0Size) * kALignForN * bDtypeSize_;
        }
    }
    OP_LOGI(args_.opName, "final workspace size is %lu", workspaceSize_);
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus AiInfraMatmulBaseTiling::PostTiling()
{
    size_t tilingDataSize = sizeof(AiInfraMatmulTilingData);
    OP_TILING_CHECK(tilingDataSize % sizeof(uint64_t) != 0,
                    OP_LOGE(args_.opName, "tiling data size[%zu] is not aligned to 8", tilingDataSize),
                    return ge::GRAPH_FAILED);
    OPS_CHECK_NULL_WITH_CONTEXT(context_, context_->GetRawTilingData());
    errno_t ret = memcpy_s(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity(),
                           reinterpret_cast<void *>(&tilingData_), tilingDataSize);
    if (ret != EOK) {
        OP_LOGE(context_->GetNodeName(), "memcpy_s failed, ret=%d", ret);
        return ge::GRAPH_FAILED;
    }
    context_->GetRawTilingData()->SetDataSize(tilingDataSize);
    context_->SetBlockDim(tilingData_.matmulTiling.usedCoreNum);
    // SyncAll和CrossCoreSetFlag<0>属于核间同步，需要设置ScheduleMode为1
    // 含核间同步的场景：
    //   1. MIXND2NZ == V_HEAD_ND2NZ (nd2nz场景，MatmulBaseUnAlignedKernel等含SyncAll)
    //   2. SPLITCOREMODE != BASE
    //   (所有非BASE切K模式：SC_SPLIT_K/NKM/GM_TO_L1/DETERMINISTIC含SyncAll，MULTI_CORE含CrossCoreSetFlag<0>)
    // 不含核间同步的场景（仅CrossCoreSetFlag<0x2>或无同步）：
    //   BASE + MIXND2NZ != V_HEAD_ND2NZ (任意FIXOPTI)
    //   包括MatmulBaseKernel、AL1/BL1FullLoad、UnalignedNKernel(0x2)、CvpBaseKernel(0x2)
    context_->SetScheduleMode(0);
    size_t *workspaces = context_->GetWorkspaceSizes(1); // set workspace
    OP_TILING_CHECK(workspaces == nullptr, CUBE_INNER_ERR_REPORT(context_->GetNodeName(), "workspaces is null"),
                    return ge::GRAPH_FAILED);
    workspaces[0] = workspaceSize_;

    return ge::GRAPH_SUCCESS;
}
} // namespace ai_infra_matmul
} // namespace optiling

