37	class TilingCases {
38	public:
39	    explicit TilingCases(std::string op_type) : op_type_(std::move(op_type))
40	    {}
41	
42	    template <typename T>
43	    void AddTiling(int32_t priority)
44	    {
45	        OP_CHECK_IF(
46	            cases_.find(priority) != cases_.end(), OP_LOGE(op_type_, "There are duplicate registrations."), return);
47	        cases_[priority] = TILING_CLASS<T>;
48	        OP_CHECK_IF(
49	            cases_[priority] == nullptr,
50	            OP_LOGE(op_type_, "Register op tiling func failed, please check the class name."), return);
51	    }
