63	// --------------------------------Interfacce with npu arch --------------------------------
64	class TilingRegistryArch {
65	public:
66	    TilingRegistryArch() = default;
67	
68	#ifdef ASCENDC_OP_TEST
69	    static TilingRegistryArch& GetInstance();
70	#else
71	    static TilingRegistryArch& GetInstance()
72	    {
73	        static TilingRegistryArch registryImpl;
74	        return registryImpl;
75	    }
76	#endif
77	
78	    std::shared_ptr<TilingCases> RegisterOp(const std::string& opType, int32_t arch)
79	    {
80	        auto archIter = registryMap_.find(arch);
81	        if (archIter == registryMap_.end()) {
82	            std::map<std::string, std::shared_ptr<TilingCases>> opTypeMap;
83	            opTypeMap[opType] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(opType));
84	            registryMap_[arch] = opTypeMap;
85	        } else {
86	            if (archIter->second.find(opType) == archIter->second.end()) {
87	                archIter->second[opType] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(opType));
88	            }
89	        }
90	
91	        OP_CHECK_IF(registryMap_[arch][opType] == nullptr,
92	            OP_LOGE(opType, "Register tiling func failed, please check the class name."), return nullptr);
93	        return registryMap_[arch][opType];
94	    }
95	
96	    ge::graphStatus DoTilingImpl(gert::TilingContext* context)
97	    {
98	        int32_t arch = (int32_t)NpuArch::DAV_RESV;
99	        const char* opType = context->GetNodeType();
100	        fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
101	        if (platformInfoPtr == nullptr) {
102	            OP_LOGE(opType, "Do op tiling failed, cannot get platformInfo.");
103	            return ge::GRAPH_FAILED;
104	        } else {
105	            auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
106	            arch = static_cast<int32_t>(ascendcPlatform.GetCurNpuArch());
107	            OP_LOGD(context, "npu arch is %d", arch);
108	            if (arch == (int32_t)NpuArch::DAV_RESV) {
109	                OP_LOGE(opType, "Do op tiling failed, cannot find npu arch.");
110	                return ge::GRAPH_FAILED;
111	            }
112	        }
113	        auto tilingTemplateRegistryMap = GetTilingTemplates(opType, arch);
114	        for (auto it = tilingTemplateRegistryMap.begin(); it != tilingTemplateRegistryMap.end(); ++it) {
115	            auto tilingTemplate = it->second(context);
116	            if (tilingTemplate != nullptr) {
117	                ge::graphStatus status = tilingTemplate->DoTiling();
118	                if (status != ge::GRAPH_PARAM_INVALID) {
119	                    OP_LOGD(context, "Do general op tiling success priority=%d", it->first);
120	                    return status;
121	                }
122	                OP_LOGD(context, "Ignore general op tiling priority=%d", it->first);
123	            }
124	        }
125	        OP_LOGE(opType, "Do op tiling failed, no valid template is found.");
126	        return ge::GRAPH_FAILED;
127	    }
128	
129	    const std::map<int32_t, TilingClassCase>& GetTilingTemplates(const std::string& opType, int32_t arch)
130	    {
131	        auto archIter = registryMap_.find(arch);
132	        OP_CHECK_IF(archIter == registryMap_.end(),
133	            OP_LOGE(opType, "Get op tiling func failed, please check the npu arch %d", arch),
134	            return emptyTilingCase_);
135	        auto opIter = archIter->second.find(opType);
136	        OP_CHECK_IF(
137	            opIter == archIter->second.end(), OP_LOGE(opType, "Get op tiling func failed, please check the op name."),
138	            return emptyTilingCase_);
139	        return opIter->second->GetTilingCases();
140	    }
141	
142	private:
143	    std::map<int32_t, std::map<std::string, std::shared_ptr<TilingCases>>> registryMap_; // key is npu-arch
144	    const std::map<int32_t, TilingClassCase> emptyTilingCase_{};
145	};
