147	class RegisterArch {
148	public:
149	    explicit RegisterArch(std::string opType) : opType_(std::move(opType))
150	    {}
151	
152	    template <typename T>
153	    RegisterArch& tiling(int32_t priority, int32_t arch)
154	    {
155	        auto tilingCases = TilingRegistryArch::GetInstance().RegisterOp(opType_, arch);
156	        OP_CHECK_IF(
157	            tilingCases == nullptr, OP_LOGE(opType_, "Register op tiling failed, please check the op name."),
158	            return *this);
159	        tilingCases->AddTiling<T>(priority);
160	        return *this;
161	    }
162	
163	    template <typename T>
164	    RegisterArch& tiling(int32_t priority, const std::vector<int32_t>& archs)
165	    {
166	        for (int32_t arch : archs) {
167	            auto tilingCases = TilingRegistryArch::GetInstance().RegisterOp(opType_, arch);
168	            OP_CHECK_IF(
169	                tilingCases == nullptr, OP_LOGE(opType_, "Register op tiling failed, please check the op name."),
170	                return *this);
171	            tilingCases->AddTiling<T>(priority);
172	        }
173	        return *this;
174	    }
175	
176	private:
177	    const std::string opType_;
178	};
