192	    }
193	#endif
194	
195	    std::shared_ptr<TilingCases> RegisterOp(const std::string& op_type, int32_t soc_version)
196	    {
197	        auto soc_iter = registry_map_.find(soc_version);
198	        if (soc_iter == registry_map_.end()) {
199	            std::map<std::string, std::shared_ptr<TilingCases>> op_type_map;
200	            op_type_map[op_type] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(op_type));
201	            registry_map_[soc_version] = op_type_map;
202	        } else {
203	            if (soc_iter->second.find(op_type) == soc_iter->second.end()) {
204	                soc_iter->second[op_type] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(op_type));
205	            }
206	        }
207	
208	        OP_CHECK_IF(
209	            registry_map_[soc_version][op_type] == nullptr,
210	            OP_LOGE(op_type, "Register tiling func failed, please check the class name."), return nullptr);
211	        return registry_map_[soc_version][op_type];
212	    }
213	
214	    ge::graphStatus DoTilingImpl(gert::TilingContext* context)
215	    {
216	        int32_t soc_version = (int32_t)platform_ascendc::SocVersion::RESERVED_VERSION;
217	        const char* opType = context->GetNodeType();
218	        fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
219	        if (platformInfoPtr == nullptr) {
220	            auto compileInfoPtr = context->GetCompileInfo<CompileInfoCommon>();
221	            OP_CHECK_IF(
222	                compileInfoPtr == nullptr, OP_LOGE(opType, "compileInfoPtr is null."), return ge::GRAPH_FAILED);
223	            soc_version = compileInfoPtr->socVersion;
224	            OP_LOGD(context, "soc version in compileInfo is %d", soc_version);
225	        } else {
226	            auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
227	            soc_version = static_cast<int32_t>(ascendcPlatform.GetSocVersion());
228	            OP_LOGD(context, "soc version is %d", soc_version);
229	            if (soc_version == (int32_t)platform_ascendc::SocVersion::RESERVED_VERSION) {
230	                OP_LOGE(opType, "Do op tiling failed, cannot find soc version.");
231	                return ge::GRAPH_FAILED;
232	            }
233	        }
234	        auto tilingTemplateRegistryMap = GetTilingTemplates(opType, soc_version);
235	        for (auto it = tilingTemplateRegistryMap.begin(); it != tilingTemplateRegistryMap.end(); ++it) {
236	            auto tilingTemplate = it->second(context);
237	            if (tilingTemplate != nullptr) {
238	                ge::graphStatus status = tilingTemplate->DoTiling();
239	                if (status != ge::GRAPH_PARAM_INVALID) {
240	                    OP_LOGD(context, "Do general op tiling success priority=%d", it->first);
241	                    return status;
242	                }
243	                OP_LOGD(context, "Ignore general op tiling priority=%d", it->first);
244	            }
245	        }
246	        OP_LOGE(opType, "Do op tiling failed, no valid template is found.");
247	        return ge::GRAPH_FAILED;
248	    }
249	
250	    ge::graphStatus DoTilingImpl(gert::TilingContext* context, const std::vector<int32_t>& priorities)
251	    {
252	        int32_t soc_version;
253	        const char* opType = context->GetNodeType();
254	        auto platformInfoPtr = context->GetPlatformInfo();
255	        if (platformInfoPtr == nullptr) {
256	            auto compileInfoPtr = context->GetCompileInfo<CompileInfoCommon>();
257	            OP_CHECK_IF(
258	                compileInfoPtr == nullptr, OP_LOGE(opType, "compileInfoPtr is null."), return ge::GRAPH_FAILED);
259	            soc_version = compileInfoPtr->socVersion;
260	            OP_LOGD(context, "soc version in compileInfo is %d", soc_version);
261	        } else {
262	            auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
263	            soc_version = static_cast<int32_t>(ascendcPlatform.GetSocVersion());
264	            OP_LOGD(context, "soc version is %d", soc_version);
265	        }
266	
267	        auto tilingTemplateRegistryMap = GetTilingTemplates(opType, soc_version);
268	        for (auto priority_id : priorities) {
269	            auto tilingCaseIter = tilingTemplateRegistryMap.find(priority_id);
270	            if (tilingCaseIter != tilingTemplateRegistryMap.end()) {
271	                auto templateFunc = tilingCaseIter->second(context);
272	                if (templateFunc != nullptr) {
273	                    ge::graphStatus status = templateFunc->DoTiling();
274	                    if (status == ge::GRAPH_SUCCESS) {
275	                        OP_LOGD(context, "Do general op tiling success priority=%d", priority_id);
276	                        return status;
277	                    }
278	                    OP_LOGD(context, "Ignore general op tiling priority=%d", priority_id);
279	                }
280	            }
281	        }
282	        return ge::GRAPH_FAILED;
283	    }
284	
285	    const std::map<int32_t, TilingClassCase>& GetTilingTemplates(const std::string& op_type, int32_t soc_version)
286	    {
287	        auto soc_iter = registry_map_.find(soc_version);
288	        OP_CHECK_IF(
289	            soc_iter == registry_map_.end(),
290	            OP_LOGE(op_type, "Get op tiling func failed, please check the soc version %d", soc_version),
291	            return empty_tiling_case_);
292	        auto op_iter = soc_iter->second.find(op_type);
293	        OP_CHECK_IF(
294	            op_iter == soc_iter->second.end(), OP_LOGE(op_type, "Get op tiling func failed, please check the op name."),
295	            return empty_tiling_case_);
296	        return op_iter->second->GetTilingCases();
297	    }
298	
299	private:
300	    std::map<int32_t, std::map<std::string, std::shared_ptr<TilingCases>>> registry_map_; // key is socversion
301	    const std::map<int32_t, TilingClassCase> empty_tiling_case_{};
302	};
