inline void ResetBase(AiInfraMatmulRunInfo &runInfo, const uint64_t l0CSize, const uint64_t dTypeSize = 2)
{
    runInfo.baseM = (l0CSize == L0C_SIZE_256_KB) ? BASIC_BLOCK_SIZE_256 : BASIC_BLOCK_SIZE_128;
