__aicore__ inline void AiInfraMatmulCvpBaseKernel<A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, BLOCK_TYPE, MM_CFG,
    MM_CB>::AivProcess(
    uint32_t pingpong_gm)
{
    if ASCEND_IS_AIC {
        return;
    }
    GlobalTensor<A_T> curGlobal;
    uint64_t curOffset;
    uint32_t nCalcLen, dCalcLen;

    if (aNz) {
        curGlobal = this->aGlobal_;
        curOffset = this->block_.offset_.offsetA;
        nCalcLen = this->block_.params_.isTransposeA
            ? this->block_.matmulTilingData_->matmulTiling.singleCoreK : this->block_.params_.singleCoreM;
        dCalcLen = this->block_.params_.isTransposeA
            ? this->block_.params_.singleCoreM : this->block_.matmulTilingData_->matmulTiling.singleCoreK;
    } else {
        curGlobal = this->bGlobal_;
        curOffset = this->block_.offset_.offsetB;
        nCalcLen = this->block_.params_.isTransposeB
            ? this->block_.params_.singleCoreN : this->block_.matmulTilingData_->matmulTiling.singleCoreK;
        dCalcLen = this->block_.params_.isTransposeB
            ? this->block_.matmulTilingData_->matmulTiling.singleCoreK : this->block_.params_.singleCoreN;
    }
    CrossCoreWaitFlag(C_NOTIFY_V + pingpong_gm);
#if defined(__DAV_C220_VEC__)
    auto&& tempDst = wsGlobal_[pingpong_gm * oneBufferSize];
    auto&& tempSrc = curGlobal[curOffset];
