148	__aicore__ inline void AiInfraMatmulBaseKernel<A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, BLOCK_TYPE, MM_CFG, MM_CB>::Process(
149	    uint64_t index, uint8_t enAtomic)
150	{
151	    if ASCEND_IS_AIV {
152	        return;
153	    }
154	    mm_.SetHF32(false, 0);
155	    if (block_.params_.isHf32) {
156	        mm_.SetHF32(true, 1);
157	    }
158	    bool reverse = true;
159	    for (uint64_t mTileIndex = 0; mTileIndex < block_.params_.mTileCntL2; mTileIndex++) {
160	        reverse = !reverse;
161	        for (uint64_t nTileIndexTemp = 0; nTileIndexTemp < block_.params_.nTileCntL2; nTileIndexTemp++) {
162	            uint64_t nTileIndex = reverse ? (block_.params_.nTileCntL2 - nTileIndexTemp - 1) : nTileIndexTemp;
163	            block_.UpdateBlockCnt(mTileIndex, nTileIndex);
164	            block_.InitBlockIndex(index);
165	            for (uint64_t j = 0; j < block_.params_.realRound; j++) {
166	                if (block_.params_.rowOrder == 0) {
167	                    block_.UpdateBasicIndex(j); // 使能错位分核更新Index
168	                }
169	                if (block_.params_.index < block_.params_.totalTileCnt) {
170	                    block_.UpdateBlockParams(mTileIndex, nTileIndex);
171	
172	                    block_.template CalcGMOffset<A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE>(mTileIndex, nTileIndex);
173	
174	                    mm_.SetSingleShape(block_.params_.singleCoreM, block_.params_.singleCoreN,
175	                        block_.matmulTilingData_->matmulTiling.singleCoreK);
176	                    mm_.SetTensorA(aGlobal_[block_.offset_.offsetA], block_.params_.isTransposeA);
177	                    mm_.SetTensorB(bGlobal_[block_.offset_.offsetB], block_.params_.isTransposeB);
178	                    if (block_.matmulTilingData_->matmulTiling.isBias) {
179	                        mm_.SetBias(biasGlobal_[block_.offset_.offsetBias]);
180	                    }
181	                    mm_.Iterate();
182	
183	#if (defined(__NPU_ARCH__) && (__NPU_ARCH__ == 3003 || __NPU_ARCH__ == 3113))
184	                    if constexpr (IsSameType<C_T, float>::value) {
185	                        LocalTensor<half> cLocalHalf_ = cLocalHalfQue.AllocTensor<half>();
186	                        mm_.GetTensorC(cLocalHalf_, enAtomic);
187	                        uint64_t computeSize = block_.params_.singleCoreM * block_.params_.singleCoreN;
188	                        cLocalHalfQue.EnQue(cLocalHalf_);
189	                        cLocalHalfQue.DeQue<half>();
190	                        LocalTensor<float> cLocalFloat_ = cLocalFloatQue.AllocTensor<float>();
191	                        Cast(cLocalFloat_, cLocalHalf_, AscendC::RoundMode::CAST_NONE, computeSize);
192	                        cLocalFloatQue.EnQue(cLocalFloat_);
193	                        cLocalFloatQue.DeQue<float>();
194	                        DataCopy(cGlobal_[block_.offset_.offsetC], cLocalFloat_, computeSize);
195	                        cLocalHalfQue.FreeTensor(cLocalHalf_);
196	                        cLocalFloatQue.FreeTensor(cLocalFloat_);
197	                    } else {
198	                        mm_.GetTensorC(cGlobal_[block_.offset_.offsetC], enAtomic);
199	                    }
200	#else
201	                    mm_.GetTensorC(cGlobal_[block_.offset_.offsetC], enAtomic);
202	#endif
203	
204	#if defined(__CCE_AICORE__) && __CCE_AICORE__ < 220
205	                    SetFlag<HardEvent::MTE3_MTE2>(EVENT_ID7);
206	                    WaitFlag<HardEvent::MTE3_MTE2>(EVENT_ID7);
207	#endif
208	                }
209	                block_.UpdateBlockIndex();
210	            }
211	        }
212	    }
213	    PipeBarrier<PIPE_ALL>();
214	    SetAtomicNone();
215	    mm_.SetHF32(false, 0);
216	    return;
217	}
218	#endif // MMV3_MATMUL_KERNEL_H
